import React, { useState } from "react";
import StudentForm from "./components/StudentForm";
import StudentList from "./components/StudentList";
import StudentDetails from "./components/StudentDetails";
import "./styles.css";


export default function App() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);

  const addStudent = (s) => {
    setStudents([...students, { ...s, id: Date.now() }]);
  };

  return (
    <div className="app-container">
      <h1 className="title">Student Result Dashboard</h1>

      <div className="layout">
        <div className="left-panel">
          <StudentForm onAdd={addStudent} />
          <StudentList students={students} onSelect={setSelected} />
        </div>

        <div className="right-panel">
          {selected ? <StudentDetails student={selected} /> : <p>Select a student to view details.</p>}
        </div>
      </div>
    </div>
  );
}
